import { useState } from "react";
import axios from "axios";

function MedicalForm() {
  const [age, setAge] = useState("");
  const [gender, setGender] = useState("");
  const [duration, setDuration] = useState("");
  const [issues, setIssues] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const submit = async () => {
    if (!issues.trim()) {
      alert("Please describe your symptoms");
      return;
    }
    setLoading(true);
    try {
      const res = await axios.post("http://127.0.0.1:5000/predict_text", {
        age,
        gender,
        duration,
        text: issues
      });
      setResult(res.data);
    } catch (error) {
      alert("Error connecting to server");
    }
    setLoading(false);
  };

  return (
    <div style={{padding:"30px", fontFamily:"Arial", maxWidth:"600px", margin:"auto"}}>
      <h1 style={{color:"#2c3e50"}}>🩺 AI Health Symptom Checker</h1>

      <div style={{marginBottom:"15px"}}>
        <label>Age: </label>
        <input type="number" style={{padding:"8px", width:"100px"}} onChange={e=>setAge(e.target.value)} />
      </div>

      <div style={{marginBottom:"15px"}}>
        <label>Gender: </label>
        <select style={{padding:"8px"}} onChange={e=>setGender(e.target.value)}>
          <option>Select</option>
          <option>Male</option>
          <option>Female</option>
        </select>
      </div>

      <div style={{marginBottom:"15px"}}>
        <label>Duration (days): </label>
        <input type="number" style={{padding:"8px", width:"100px"}} onChange={e=>setDuration(e.target.value)} />
      </div>

      <h3 style={{marginTop:"20px"}}>Describe your health issues</h3>
      <textarea 
        rows="4" 
        style={{width:"100%", padding:"10px", fontSize:"16px"}}
        placeholder="Example: I have fever, headache, stomach pain, vomiting..."
        onChange={e=>setIssues(e.target.value)}
      ></textarea>
      <br/><br/>

      <button 
        onClick={submit} 
        disabled={loading}
        style={{
          padding:"12px 30px", 
          fontSize:"16px", 
          backgroundColor:"#3498db", 
          color:"white", 
          border:"none", 
          borderRadius:"5px",
          cursor:"pointer"
        }}
      >
        {loading ? "Analyzing..." : "Check Symptoms"}
      </button>

      {result && result.confidence > 0 && (
        <div style={{
          marginTop:"25px", 
          border:"2px solid #3498db", 
          borderRadius:"10px",
          padding:"20px",
          backgroundColor:"#f8f9fa"
        }}>
          <h2 style={{color:"#2c3e50", marginBottom:"15px"}}>🔍 Analysis Result</h2>
          
          <div style={{backgroundColor:"white", padding:"15px", borderRadius:"8px", marginBottom:"15px"}}>
            <h3 style={{margin:"0", color:"#2c3e50"}}>Most Likely Condition:</h3>
            <p style={{fontSize:"24px", fontWeight:"bold", color:"#e74c3c", margin:"10px 0"}}>{result.disease}</p>
            <p style={{margin:"0", color:"#7f8c8d"}}>Confidence: <strong>{result.confidence}%</strong></p>
          </div>

          {result.possible_conditions && result.possible_conditions.length > 0 && (
            <div style={{backgroundColor:"white", padding:"15px", borderRadius:"8px", marginBottom:"15px"}}>
              <h4 style={{margin:"0 0 10px 0", color:"#2c3e50"}}>Other Possible Conditions:</h4>
              <ul style={{margin:"0", paddingLeft:"20px"}}>
                {result.possible_conditions.map((condition, idx) => (
                  <li key={idx} style={{color:"#666", marginBottom:"5px"}}>{condition}</li>
                ))}
              </ul>
            </div>
          )}

          <div style={{
            backgroundColor: result.urgency === "High" ? "#ffebee" : result.urgency === "Medium" ? "#fff3e0" : "#e8f5e9",
            padding:"15px", 
            borderRadius:"8px",
            marginBottom:"15px"
          }}>
            <h3 style={{margin:"0 0 10px 0"}}>Urgency Level: 
              <span style={{
                color: result.urgency === "High" ? "#c62828" : result.urgency === "Medium" ? "#ef6c00" : "#2e7d32",
                marginLeft:"10px"
              }}>
                {result.urgency === "High" ? "⚠️ " : result.urgency === "Medium" ? "⚡ " : "✅ "}
                {result.urgency}
              </span>
            </h3>
          </div>
          
          {result.symptoms_detected && result.symptoms_detected.length > 0 && (
            <p style={{color:"#555"}}>
              <strong>Symptoms Identified:</strong> {result.symptoms_detected.map(s => s.replace(/_/g, " ")).join(", ")}
            </p>
          )}

          {result.urgency === "High" && (
            <div style={{backgroundColor:"#c62828", color:"white", padding:"15px", borderRadius:"8px", textAlign:"center"}}>
              <h3 style={{margin:"0"}}>⚠️ Please consult a doctor immediately!</h3>
            </div>
          )}

          <p style={{fontSize:"12px", color:"#999", marginTop:"15px"}}>
            ⚕️ Disclaimer: This is an AI-based prediction. Please consult a healthcare professional for accurate diagnosis.
          </p>
        </div>
      )}

      {result && result.confidence === 0 && (
        <div style={{marginTop:"20px", padding:"15px", backgroundColor:"#fff3cd", borderRadius:"8px"}}>
          <p style={{margin:"0", color:"#856404"}}>{result.message}</p>
        </div>
      )}
    </div>
  );
}

export default MedicalForm;
